type Attachment = ChatAttachmentInfo & { dataUri?: string; uploadStatus?: "uploading" | "ready" | "retrying" | "failed"; progress?: number; size?: number; sourceFileName?: string };
type Message = AiraChatMessage & { attachment?: Attachment; isDraft?: boolean; draft?: { kind: "income" | "expense"; amount: number; category: string; note: string } };
type AiraGenerationKind = "image" | "pdf" | "word" | "powerpoint" | "excel" | "markdown" | "text";
const id = () => `${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
const stored = (message: Message): AiraChatMessage => ({ id: message.id, role: message.role, content: message.content, createdAt: message.createdAt, attachment: message.attachment ? { uri: message.attachment.uri, kind: message.attachment.kind, mimeType: message.attachment.mimeType, label: message.attachment.label, generationPrompt: message.attachment.generationPrompt, generationKind: message.attachment.generationKind, generationQuality: message.attachment.generationQuality } : undefined, suggestedMemory: message.suggestedMemory, expert: message.expert });
const title = (messages: Message[]) => messages.find((item) => item.role === "user")?.content.replace(/\s+/g, " ").slice(0, 46) || "Percakapan baru";
const MAX_MEDIA_BYTES = 200 * 1024 * 1024;
const AIRA_CLIENT_RESPONSE_TIMEOUT_MS = 45_000;
const DEFAULT_AIRA_AVATAR = require("../assets/images/vairaa-profile.png");
const HOT_PRO_AVATAR = require("../assets/images/aira-hot-pro-avatar.png");
const EXPERT_AVATARS: Record<NonNullable<AiraChatMessage["expert"]>["id"], number> = { general: require("../assets/images/expert-general.png"), religion: require("../assets/images/expert-religion.png"), medical: require("../assets/images/expert-medical.png"), psychology: require("../assets/images/expert-psychology.png"), philosophy: require("../assets/images/expert-philosophy.png"), law: require("../assets/images/expert-law.png"), finance: require("../assets/images/expert-finance.png"), technology: require("../assets/images/expert-technology.png"), education: require("../assets/images/expert-education.png"), business: require("../assets/images/expert-business.png") };

function detectGenerationRequest(value: string): { kind: AiraGenerationKind; prompt: string } | { kind: "video" | "audio"; prompt: string } | null {
  const prompt = value.trim(); const lower = prompt.toLowerCase();
  if (!/(buat(?:kan|lah)?|generate|hasilkan|ciptakan|jadikan|tolong.*(?:gambar|foto|file|dokumen|video|audio))/i.test(lower)) return null;
  if (/\b(video|film|animasi)\b/i.test(lower)) return { kind: "video", prompt };
  if (/\b(audio|musik|lagu|suara|podcast)\b/i.test(lower)) return { kind: "audio", prompt };
  if (/\b(pdf)\b/i.test(lower)) return { kind: "pdf", prompt };
  if (/\b(word|docx?|surat)\b/i.test(lower)) return { kind: "word", prompt };
  if (/\b(ppt|powerpoint|presentasi|slide)\b/i.test(lower)) return { kind: "powerpoint", prompt };
  if (/\b(excel|xlsx?|spreadsheet|tabel kerja)\b/i.test(lower)) return { kind: "excel", prompt };
  if (/\b(markdown|\.md)\b/i.test(lower)) return { kind: "markdown", prompt };
  if (/\b(teks|txt)\b/i.test(lower)) return { kind: "text", prompt };
  if (/\b(gambar|foto|ilustrasi|poster|logo|visual|image)\b/i.test(lower)) return { kind: "image", prompt };
  return null;
}

function withClientTimeout<T>(promise: Promise<T>, milliseconds: number, message: string) {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(message)), milliseconds);
    promise.then((value) => { clearTimeout(timer); resolve(value); }, (error) => { clearTimeout(timer); reject(error); });
  });
}

